import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CANn83f8.js";const p=JSON.parse('{"title":"Categories","description":"Organise transactions and control how they appear in dashboards and reports.","frontmatter":{"title":"Categories","description":"Organise transactions and control how they appear in dashboards and reports.","aside":true,"prev":{"text":"Budgets","link":"/features/budgets"},"next":{"text":"Goals","link":"/features/goals"}},"headers":[],"relativePath":"features/categories.md","filePath":"features/categories.md","lastUpdated":1790704129000}'),s={name:"features/categories.md"};function n(i,e,l,c,g,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<div class="doc-eyebrow">Features</div><h1 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h1><p>Categories organise transactions for dashboards, reports, and spending analysis. Use them for areas such as groceries, dining, utilities, salary, or transfers.</p><div class="info custom-block"><p class="custom-block-title">Premium feature</p><p>Creating, editing, and assigning custom categories requires Premium. Household members also need permission to edit shared data.</p></div><h2 id="manage-categories" tabindex="-1">Manage categories <a class="header-anchor" href="#manage-categories" aria-label="Permalink to &quot;Manage categories&quot;">​</a></h2><p>Open <strong>Setup → Categories</strong>. Each category card shows its name, icon, colour, group, and any reporting options.</p><p>To create a category:</p><ol><li>Select <strong>Add category</strong>.</li><li>Enter a name.</li><li>Optionally choose a group.</li><li>Select a colour and icon.</li><li>Configure any reporting options.</li><li>Select <strong>Save category</strong>.</li></ol><p>Use the pencil button on a category card to edit it.</p><h3 id="names-and-groups" tabindex="-1">Names and groups <a class="header-anchor" href="#names-and-groups" aria-label="Permalink to &quot;Names and groups&quot;">​</a></h3><ul><li>Names must be unique within the same group.</li><li><strong>Uncategorized</strong> is reserved and cannot be used.</li><li>A category can belong to one top-level group.</li><li>Groups cannot be nested.</li></ul><p>For example, create <strong>Food</strong> as a group and add <strong>Groceries</strong>, <strong>Dining</strong>, and <strong>Takeaway</strong> beneath it.</p><h2 id="assign-a-category" tabindex="-1">Assign a category <a class="header-anchor" href="#assign-a-category" aria-label="Permalink to &quot;Assign a category&quot;">​</a></h2><p>Open a transaction, choose a value from <strong>Category</strong>, and save the transaction. You can also filter the transaction list by category.</p><div class="warning custom-block"><p class="custom-block-title">Category and budget assignments</p><p>A transaction can have either a custom category or a budget assignment. Assigning a category removes its existing budget assignment.</p></div><p>For repeated transactions, use a <a href="./rules">rule</a> to assign the category automatically.</p><h2 id="reporting-options" tabindex="-1">Reporting options <a class="header-anchor" href="#reporting-options" aria-label="Permalink to &quot;Reporting options&quot;">​</a></h2><h3 id="treat-as-transfer" tabindex="-1">Treat as transfer <a class="header-anchor" href="#treat-as-transfer" aria-label="Permalink to &quot;Treat as transfer&quot;">​</a></h3><p>Enable <strong>Treat as transfer</strong> for money moved between accounts you own. These transactions remain visible but are excluded from income and expense totals.</p><p>Examples include transfers to savings or payments between your own accounts.</p><h3 id="ignore-in-reports" tabindex="-1">Ignore in reports <a class="header-anchor" href="#ignore-in-reports" aria-label="Permalink to &quot;Ignore in reports&quot;">​</a></h3><p>Enable <strong>Ignore in reports</strong> to keep transactions visible while excluding them from dashboard totals, charts, analytics, and reports.</p><p>Changing either option affects transactions already assigned to the category and may change existing totals.</p><h2 id="current-limitations" tabindex="-1">Current limitations <a class="header-anchor" href="#current-limitations" aria-label="Permalink to &quot;Current limitations&quot;">​</a></h2><ul><li>Categories cannot currently be deleted from the Categories page.</li><li>Groups support one level only.</li><li>Free accounts can preview categories but cannot assign or manage them.</li></ul><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./transactions">Transactions</a></li><li><a href="./budgets">Budgets</a></li><li><a href="./rules">Rules</a></li><li><a href="./reports">Reports</a></li></ul>',27)])])}const h=a(s,[["render",n]]);export{p as __pageData,h as default};
